/**
 * The TypeScript core must reproduce the Python package exactly.
 *
 * test/fixtures/parity.json is generated by scripts/export_parity.py from the
 * Python package: every benchmark sentence (dev + holdout) plus edge cases,
 * with the detections and masked text Python produces.
 */

import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { test } from "node:test";

import { Kavach } from "../src/core/index.ts";

interface Case {
  id: string;
  text: string;
  detections: [string, number, number, number][];
  masked: string;
}

const fixture = JSON.parse(
  readFileSync(new URL("./fixtures/parity.json", import.meta.url), "utf-8"),
) as { cases: Case[] };

/** Python offsets count code points; JavaScript's count UTF-16 units. */
function codePoints(text: string, utf16Index: number): number {
  return [...text.slice(0, utf16Index)].length;
}

const kavach = new Kavach();

test("fixture covers the benchmark and edge cases", () => {
  assert.ok(fixture.cases.length > 2000);
  assert.ok(fixture.cases.some((c) => c.id.startsWith("edge-")));
});

test("detections match Python for every case", () => {
  const mismatches: string[] = [];
  for (const c of fixture.cases) {
    const actual = kavach
      .scan(c.text)
      .map((d) => [d.entityType, codePoints(c.text, d.start), codePoints(c.text, d.end), d.score]);
    const same =
      actual.length === c.detections.length &&
      actual.every((a, i) => {
        const e = c.detections[i]!;
        return a[0] === e[0] && a[1] === e[1] && a[2] === e[2] && Math.abs((a[3] as number) - e[3]) < 1e-9;
      });
    if (!same) {
      mismatches.push(
        `${c.id}\n  python: ${JSON.stringify(c.detections)}\n  ts:     ${JSON.stringify(actual)}`,
      );
    }
  }
  assert.equal(mismatches.length, 0, `${mismatches.length} mismatches:\n${mismatches.slice(0, 10).join("\n")}`);
});

test("masked text matches Python for every case", () => {
  const mismatches = fixture.cases
    .filter((c) => kavach.session().mask(c.text) !== c.masked)
    .map((c) => c.id);
  assert.deepEqual(mismatches, []);
});
